func uintToStr(v uint32) string {
	if v == 0 {
		return ""
	}
	return fmt.Sprintf("%d", v)
}

// composeDefaultBodyMode returns "plain" for reply/forward modes and "rich" for
// new messages. This is rendered into the Alpine x-data initial state so that
// the body_mode form field defaults correctly without requiring JavaScript logic.
func composeDefaultBodyMode(mode string) string {
	if mode == "reply" || mode == "forward" {
		return "plain"
	}
	return "rich"
}

// composeInitialBody returns the body text used to seed the richEditor for
// reply and forward modes (quoted text + plain signature). For new messages it
// returns an empty string so the editor starts blank — the server appends the
// HTML signature in rich mode, avoiding double-application.
func composeInitialBody(mode, body string) string {
	if mode == "reply" || mode == "forward" {
		return body
	}
	return ""
}

